= xi.zone.GARLAIGE_CITADEL,\n    optionalArtifact1 = xi.item.TEMPLE_CYCLAS,\n    optionalArtifact2 = xi.item.TEMPLE_CROWN,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Vermillion_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Vermillion_Hands.lua",["SHA256"]="9fb246b545db6574a772f900725dea78e0c00e7e905a9287e719620387cc837e",["Text"]="-----------------------------------\n-- Borghertz's Vermillion Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 48\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_VERMILLION_HANDS,\n    handAFId          = xi.item.WARLOCKS_GLOVES,\n    requiredLogId     = xi.questLog.SANDORIA,\n    requiredQuestId   = xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS,\n    requiredJobId     = xi.job.RDM,\n    oldGauntletZoneId = xi.zone.THE_ELDIEME_NECROPOLIS,\n    optionalZoneId1   = xi.zone.CASTLE_OZTROJA,\n    optionalZoneId2   = xi.zone.GARLAIGE_CITADEL,\n    optionalArtifact1 = xi.item.WARLOCKS_TABARD,\n    optionalArtifact2 = xi.item.WARLOCKS_TIGHTS,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Warring_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Warring_Hands.lua",["SHA256"]="5651b6f2ff57e9802c9ab82b7dca725159e78d098461529dcd55b08f07b4e23e",["Text"]="-----------------------------------\n-- Borghertz's Warring Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 44\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_WARRING_HANDS,\n    handAFId          = xi.item.FIGHTERS_MUFFLERS,\n    requiredLogId     = xi.questLog.BASTOK,\n    requiredQuestId   = xi.quest.id.bastok.THE_TALEKEEPERS_TRUTH,\n    requiredJobId     = xi.job.WAR,\n    oldGauntletZoneId = xi.zone.THE_ELDIEME_NECROPOLIS,\n    optionalZoneId1   = xi.zone.CASTLE_ZVAHL_BAILEYS,\n    optionalZoneId2   = xi.zone.CRAWLERS_NEST,\n    optionalArtifact1 = xi.item.FIGHTERS_CUISSES,\n    optionalArtifact2 = xi.item.FIGHTERS_MASK,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Wild_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Wild_Hands.lua",["SHA256"]="f3f601c5735a42f217bd92de54ec91ef21b6da50440a9bc5ab4f35f80df95ae3",["Text"]="-----------------------------------\n-- Borghertz's Wild Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 52\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_WILD_HANDS,\n    handAFId          = xi.item.BEAST_GLOVES,\n    requiredLogId     = xi.questLog.JEUNO,\n    requiredQuestId   = xi.quest.id.jeuno.SCATTERED_INTO_SHADOW,\n    requiredJobId     = xi.job.BST,\n    oldGauntletZoneId = xi.zone.CRAWLERS_NEST,\n    optionalZoneId1   = xi.zone.BEADEAUX,\n    optionalZoneId2   = xi.zone.GARLAIGE_CITADEL,\n    optionalArtifact1 = xi.item.BEAST_JACKCOAT,\n    optionalArtifact2 = xi.item.BEAST_HELM,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Candle_Making.lua"]={["Path"]="scripts/quests/jeuno/Candle_Making.lua",["SHA256"]="59ae0e0b35716d06e2271b24eaabebd9b3b2244264aaf6dacd5bb004550dcce9",["Text"]="-----------------------------------\n-- Candle Making\n-----------------------------------\n-- !addquest 3 22\n-- Rouliette : !pos -24 -2 11 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.CANDLE_MAKING)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.HOLY_CANDLE,\n    title    = xi.title.BELIEVER_OF_ALTANA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CANDLELIGHT_VIGIL) == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Rouliette'] = quest:progressEvent(36),\n\n            onEventFinish =\n            {\n                [36] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Rouliette'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.LANOLIN_CUBE, 1 } }) then\n                        return quest:progressEvent(37)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(36)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 13)\n                        player:addFame(xi.fameArea.BASTOK, 13)\n                        player:addFame(xi.fameArea.WINDURST, 13)\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Childs_Play.lua"]={["Path"]="scripts/quests/jeuno/Childs_Play.lua",["SHA256"]="12f8d5cab8173d73f6f89ffc04b09c7caeacf68972e97fb8be8594ddea67ba6f",["Text"]="-----------------------------------\n-- Child's Play\n-----------------------------------\n-- !addquest 3 23\n-- Karl : !pos -60 0.1 -8 246\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.CHILDS_PLAY)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.WONDER_MAGIC_SET,\n    title    = xi.title.TRADER_OF_MYSTERIES,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET) == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Karl'] = quest:progressEvent(0),\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Karl'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.WHITE_ROCK) then\n                        return quest:progressEvent(1)\n                    end\n                end,\n\n                onTrigger = quest:event(61),\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Chocobo_on_the_Loose.lua"]={["Path"]="scripts/quests/jeuno/Chocobo_on_the_Loose.lua",["SHA256"]="f947757f890e5ec2b7c91fa83d5a9d7bb286deac6846fa3fd68589b0981dec78",["Text"]="-----------------------------------\n-- Chocobo on the Loose\n-----------------------------------\n-- Log ID: 3, Quest ID: 92\n-- Brutus         : !pos -55 8 95 244\n-- Chocobo Tracks : !pos -556 0 523 102\n-- Hantileon      : !pos -2.675 -1.1 -105.287 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.CHOCOBO_ON_THE_LOOSE)\n\nquest.reward =\n{\n    -- TODO: Verify this is the correct egg for Quest Reward\n    item = xi.item.CHOCOBO_EGG_FAINTLY_WARM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getMainLvl() >= 20 and xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10093)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10093] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['Chocobo_Tracks'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(209)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [209] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hantileon'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(821)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(822)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [821] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(10094):oncePerZone()\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(10095)\n                    elseif questProgress == 2 then\n                        return quest:event(10099)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(10100)\n                    elseif\n                        questProgress == 4 and\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(10109)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10095] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [10100] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setMustZone(player)\n                end,\n\n                [10109] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Chocobos_Wounds.lua"]={["Path"]="scripts/quests/jeuno/Chocobos_Wounds.lua",["SHA256"]="1ca23bbcd75eb0910ef16a754bee3430f903d8226a4b68854c96c828e76f2583",["Text"]="-----------------------------------\n-- Chocobo's Wounds\n-----------------------------------\n-- Log ID: 3, Quest ID: 4\n-- Brutus  : !pos -55 8 95 244\n-- Chocobo : !pos -61.42 8.2 93 244\n-- Osker   : !pos -61.42 8.2 94.2 244\n-- _6t2    : !pos -88.2 -7.65 -168.8 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.CHOCOBOS_WOUNDS)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.CHOCOBO_LICENSE,\n    title    = xi.title.CHOCOBO_TRAINER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getMainLvl() >= 20\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['_6t2'] = quest:event(64),\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    local declinedOption = quest:getVar(player, 'Declined') == 1 and 0 or 1\n                    return quest:progressEvent(71, declinedOption)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [71] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n\n                    -- Dialogue changes if the player fails to choose the correct option.\n                    else\n                        quest:setVar(player, 'Declined', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['_6t2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') > 3 then\n                        return quest:event(63)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:event(65)\n                    elseif questProgress == 2 then\n                        return quest:event(66)\n                    else\n                        return quest:event(102)\n                    end\n                end,\n            },\n\n            ['Chocobo'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.BUNCH_OF_GYSAHL_GREENS) > 0 then\n                        return quest:event(76)\n                    end\n\n                    if trade:getItemQty(xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS) == 0 then\n                        return quest:noAction()\n                    end\n\n                    if quest:getVar(player, 'Timer') > GetSystemTime() then\n                        return quest:event(73)\n                    end\n\n                    local eventTable =\n                    {\n                        [1] = 57,\n                        [2] = 58,\n                        [3] = 99,\n                        [4] = 59,\n                        [5] = 60,\n                        [6] = 64,\n                    }\n\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if questProgress <= 2 then\n                        return quest:progressEvent(eventTable[questProgress])\n                    end\n\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS) then\n                        return quest:progressEvent(eventTable[questProgress])\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') <= 3 then\n                        return quest:event(62)\n                    else\n                        return quest:event(63)\n                    end\n                end,\n            },\n\n            ['Osker'] =\n            {\n                onTrigger = function(player, npc)\n                    local eventTable =\n                    {\n                        [1] = 103,\n                        [2] = 51,\n                        [3] = 52,\n                        [4] = 49,\n                        [5] = 46,\n                        [6] = 47,\n                    }\n\n                    return quest:event(eventTable[quest:getVar(player, 'Prog')])\n                end,\n            },\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 45)\n                end,\n\n                [58] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 45)\n                end,\n\n                [59] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 45)\n                    player:confirmTrade()\n                end,\n\n                [60] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 45)\n                    player:confirmTrade()\n                end,\n\n                [64] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n\n                [99] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 45)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_MY_SON)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus' ] = quest:event(22), -- Always used except for importantOnce() for Chocobo on the Loose (10094)\n            ['Chocobo'] = quest:event(61),\n            ['Osker'  ] = quest:event(53),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Collect_Tarut_Cards.lua"]={["Path"]="scripts/quests/jeuno/Collect_Tarut_Cards.lua",["SHA256"]="7041fc2c71d24fb91be0ad9e156c15604975b57d293c1c18c63d979f7781e92a",["Text"]="-----------------------------------\n-- Collect Tarut Cards\n-----------------------------------\n-- Log ID: 3, Quest ID: 10\n-- Chululu : !pos -13 -6 -42 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.COLLECT_TARUT_CARDS)\n\nquest.reward =\n{\n    title = xi.title.CARD_COLLECTOR,\n}\n\nlocal tarutCards =\n{\n    xi.item.TARUT_CARD_THE_FOOL,\n    xi.item.TARUT_CARD_DEATH,\n    xi.item.TARUT_CARD_THE_HERMIT,\n    xi.item.TARUT_CARD_THE_KING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 3\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(28) -- Offers the quest\n                end,\n            },\n\n            onEventFinish =\n            {\n                [28] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveItem(player, { { tarutCards[math.randomInt(1, #tarutCards)], 5 } })\n                    then\n                        quest:begin(player)\n                        quest:setVar(player, 'Date', JstMidnight())\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.TARUT_CARD_THE_FOOL, 1 }, { xi.item.TARUT_CARD_DEATH, 1 }, { xi.item.TARUT_CARD_THE_HERMIT, 1 }, { xi.item.TARUT_CARD_THE_KING, 1 } }) then\n                        return quest:progressEvent(200) -- Finishes the quest\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if GetSystemTime() > quest:getVar(player, 'Date') then\n                        return quest:progressEvent(10112) -- A new batch of cards, once per Earth day\n                    else\n                        return quest:progressEvent(27) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10112] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveItem(player, { { tarutCards[math.randomInt(1, #tarutCards)], 5 } })\n                    then\n                        quest:setVar(player, 'Date', JstMidnight())\n                    end\n                end,\n\n                [200] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:tradeComplete()\n                        player:setVar('Quest[3][166]Date', JstMidnight()) -- All in the Cards is first offered after JST midnight\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Community_Service.lua"]={["Path"]="scripts/quests/jeuno/Community_Service.lua",["SHA256"]="047877014edf8678c5d65e61728235f14d652ba6bdb085bb2dcc1d3d3368695f",["Text"]="-----------------------------------\n-- Community Service\n-----------------------------------\n-- Log ID: 3, Quest ID: 15\n-----------------------------------\nlocal ID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.COMMUNITY_SERVICE)\n\nquest.reward =\n{\n    title    = xi.title.TORCHBEARER,\n}\n\n-- Lights the lamps\nlocal function lightLamp(player, npc, option)\n    if option == 1 then\n        local remaining = quest:getVar(player, 'Count') - 1\n        quest:setVar(player, 'Count', remaining)\n\n        npc:setAnimation(xi.animation.OPEN_DOOR)\n\n        if remaining == 0 then\n            local zone = player:getZone()\n            player:messageSpecial(ID.text.YOU_LIGHT_THE_LAMP)\n            player:messageSpecial(ID.text.LAMP_MSG_OFFSET)\n            quest:setVar(player, 'Prog', 2)\n            zone:setLocalVar('allLightsLit', 1)\n        else\n            player:messageSpecial(ID.text.YOU_LIGHT_THE_LAMP)\n            player:messageSpecial(ID.text.LAMP_MSG_OFFSET + 1, remaining)\n        end\n    end\nend\n\n-- Determines which parameter is passed when a player checks a light\nlocal function getLampParam(player, npc)\n    local npcAnimation = npc:getAnimation()\n\n    -- In progress.\n    if quest:getVar(player, 'Prog') == 1 then\n        local hour  = VanadielHour()\n        local date  = VanadielUniqueDay()\n        local timer = quest:getVar(player, 'Timer')\n        if\n            (timer == date and hour >= 18) or -- Same day flagged\n            (timer + 1 == date and hour < 1)  -- Day after it was flagged\n        then\n            if npcAnimation == xi.animation.OPEN_DOOR then\n                return 2 -- The lamp is already lit.\n            elseif npcAnimation == xi.animation.CLOSE_DOOR then\n                return 1 -- Light the lamp? Yes/No\n            end\n        elseif\n            (timer + 1 < date) or\n            (timer + 1 == date and hour >= 1)\n        then\n            return 3\n        end\n\n    -- The lamp is lit.\n    elseif npcAnimation == xi.animation.OPEN_DOOR then\n        return 5\n\n    -- You examine the lamp. It seems that it must be lit manually.\n    else\n        return 6\n    end\nend\n\n-- Stores the player name to be called lader as a string\nlocal encodeToVars = function(player)\n    local pName = player:getName()\n    local pZone = player:getZone()\n\n    local stored = { 0, 0, 0, 0 }\n    local chunk  = 1\n\n    for i = 1, #pName, 4 do\n        local v = 0\n\n        for j = 1, 4 do\n            local idx = i + j - 1\n            local c = string.byte(pName, idx)\n            if not c then\n                break\n            end\n\n            v = bit.bor(v, bit.lshift(c, (j - 1) * 8))\n        end\n\n        stored[chunk] = v\n        chunk = chunk + 1\n        if chunk > 4 then\n            break\n        end\n    end\n\n    for i, v in ipairs(stored) do\n        pZone:setLocalVar('commServicePlayer' .. i, v)\n    end\nend\n\n-- Returns the stored player name and concats it together into a single string\nlocal decodeFromVars = function(zone)\n    local chars = {}\n\n    for chunk = 1, 4 do\n        local v = zone:getLocalVar('commServicePlayer' .. chunk)\n        if v == 0 then\n            break\n        end\n\n        for j = 1, 4 do\n            local c = bit.band(bit.rshift(v, (j - 1) * 8), 0xFF)\n            if c == 0 then\n                return table.concat(chars)\n            end\n\n            chars[#chars + 1] = string.char(c)\n        end\n    end\n\n    return table.concat(chars)\nend\n\n-- This gets called from Lower Jeuno zone script at 1:00 AM\nxi.quest.communityServiceStartVhana = function(zone)\n    if zone:getLocalVar('commServiceComp') == 0 then\n        return true\n    end\n\n    return false\nend\n\n-- This gets called from Lower Jeuno zone script at 5:00 AM\nxi.quest.communityServiceCleanup = function(zone)\n    -- Reset zone variables.\n    zone:setLocalVar('commServiceStart', 0)\n    zone:setLocalVar('commServiceComp', 0)\n    zone:setLocalVar('allLightsLit', 0)\n\n    for i = 1, 4 do\n        zone:setLocalVar('commServicePlayer' .. i, 0)\n    end\n\n    -- Turn lights off.\n    for i = 0, 11 do\n        local lamp = GetNPCByID(ID.npc.STREETLAMP_OFFSET + i)\n\n        if lamp then\n            lamp:setAnimation(xi.animation.CLOSE_DOOR)\n        end\n    end\nend\n\n-- This gets called from Lower Jeuno zone script at 18:00 PM\nxi.quest.communityServiceNotification = function(zone)\n    local players = zone:getPlayers()\n\n    for _, player in pairs(players) do\n        if player:hasKeyItem(xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD) then\n            player:messageSpecial(ID.text.ZAUKO_IS_RECRUITING)\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return vars.Prog >= 0\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Zauko'] =\n            {\n                onTrigger = function(player, npc)\n                    local zone = player:getZone()\n                    if not zone then\n                        return\n                    end\n\n                    local date            = VanadielUniqueDay()\n                    local doneCommService = (player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COMMUNITY_SERVICE) == xi.questStatus.QUEST_COMPLETED) and 1 or 0\n                    local hour            = VanadielHour()\n                    local member          = player:hasKeyItem(xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD) and 1 or 0\n                    local progress        = quest:getVar(player, 'Prog')\n                    local questStarted    = zone:getLocalVar('commServiceStart') -- Either 1 or 0\n                    local questCompleted  = zone:getLocalVar('commServiceComp')  -- Either 1 or 0\n                    local timer           = quest:getVar(player, 'Timer')\n                    local playerString    = decodeFromVars(zone)\n\n                    -- Offers the quest\n                    if\n                        hour >= 18 and\n                        hour < 23 and\n                        questStarted == 0 -- Only 1 person per night can flag the quest\n                    then\n                        return quest:progressEvent(116, doneCommService)\n\n                    -- Completes the quest\n                    elseif progress == 2 then\n                        return quest:progressEvent(117, doneCommService, member) -- 0 0 = First time, 1 0 Quest completed before and does not have KI., 1 1 Has completed quest and has KI\n\n                    -- Player has the quest flagged and failed\n                    elseif\n                        progress == 1 and\n                        ((timer + 1 == date and hour >= 1) or -- Day after quest flagged\n                        (timer + 1 < date))  -- Day after it was flagged or later\n                    then\n                        return quest:progressEvent(119)\n\n                    -- Player is on the quest and has not failed/completed it yet\n                    elseif progress == 1 then\n                        return quest:event(114)\n\n                    -- Someone has completed the quest today and turned it in\n                    elseif questCompleted == 1 then\n                        if zone:getLocalVar('commServicePlayer') == player:getID() then\n                            return quest:event(113)\n                        else\n                            return quest:event(113, { [0] = questCompleted, ['strings'] = { [0] = playerString } })\n                        end\n\n                    -- Another player is on the quest and has lit all the lamps but has not turned it in yet\n                    elseif zone:getLocalVar('allLightsLit') == 1 then\n                        return quest:event(113)\n\n                    -- Asks a player with the KI if they would like to keep it. Only asks once per day.\n                    elseif\n                        hour >= 5 and\n                        hour < 18 and\n                        player:hasKeyItem(xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD) and\n                        quest:getVar(player, 'Wait') < VanadielUniqueDay()\n                    then\n                        return quest:event(118, 1)\n                    end\n                end,\n            },\n\n            ['_l00'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(120, getLampParam(player, npc), 0)\n                end\n            },\n\n            ['_l01'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(121, getLampParam(player, npc), 1)\n                end\n            },\n\n            ['_l02'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(122, getLampParam(player, npc), 2)\n                end\n            },\n\n            ['_l03'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(123, getLampParam(player, npc), 3)\n                end\n            },\n\n            ['_l04'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(124, getLampParam(player, npc), 4)\n                end\n            },\n\n            ['_l05'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(125, getLampParam(player, npc), 5)\n                end\n            },\n\n            ['_l06'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(126, getLampParam(player, npc), 6)\n                end\n            },\n\n            ['_l07'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(127, getLampParam(player, npc), 7)\n                end\n            },\n\n            ['_l08'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(128, getLampParam(player, npc), 8)\n                end\n            },\n\n            ['_l09'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(129, getLampParam(player, npc), 9)\n                end\n            },\n\n            ['_l10'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(130, getLampParam(player, npc), 10)\n                end\n            },\n\n            ['_l11'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(131, getLampParam(player, npc), 11)\n                end\n            },\n\n            onEventUpdate =\n            {\n                [116] = function(player, csid, option, npc)\n                    local zone = player:getZone()\n                    if not zone then\n                        return\n                    end\n\n                    local hour            = VanadielHour()\n                    local doneCommService = (player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COMMUNITY_SERVICE) == xi.questStatus.QUEST_COMPLETED) and 1 or 0\n                    local questStarted    = zone:getLocalVar('commServiceStart') -- Either 1 or 0\n\n                    -- Verifies if no one has accepted the quest/time has changed to too late\n                    if\n                        hour >= 18 and\n                        hour < 23 and\n                        questStarted == 0\n                    then\n                        encodeToVars(player)\n                        zone:setLocalVar('commServiceStart', 1)\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n                        quest:setVar(player, 'Count', 12)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay())\n                        player:updateEvent(1, doneCommService)\n                    else\n                        player:updateEvent(0, doneCommService) -- Someone else flagged this before they hit ok, or time ticked past the cut off.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [117] = function(player, csid, option, npc)\n                    local zone = player:getZone()\n                    if not zone then\n                        return\n                    end\n\n                    zone:setLocalVar('commServiceComp', 1)\n                    zone:setLocalVar('commServicePlayer', player:getID())\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 7)\n                    player:addFame(xi.fameArea.BASTOK, 7)\n                    player:addFame(xi.fameArea.WINDURST, 7)\n\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD)\n                    end\n                end,\n\n                [118] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Wait', VanadielUniqueDay())\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD)\n                        player:messageSpecial(ID.text.YOU_RETURN_THE, xi.keyItem.LAMP_LIGHTERS_MEMBERSHIP_CARD)\n                    end\n                end,\n\n                [119] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 0)\n                    player:setVar('Option', 0) -- Clears the local var incase the player never zones after failing\n                end,\n\n                [120] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [121] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [122] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [123] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [124] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [125] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [126] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [127] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [128] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [129] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [130] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n\n                [131] = function(player, csid, option, npc)\n                    lightLamp(player, npc, option)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Crest_of_Davoi.lua"]={["Path"]="scripts/quests/jeuno/Crest_of_Davoi.lua",["SHA256"]="6bf0b1c383a7cb19d97d331546c623818d728adf1f0efcd805669ab1b9a6009f",["Text"]="-----------------------------------\n-- Crest of Davoi\n-----------------------------------\n-- Log ID: 3, Quest ID: 0\n-- Baudin : !pos -75 0 80 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.CREST_OF_DAVOI)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.CREST_OF_DAVOI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasKeyItem(xi.keyItem.SILVER_BELL)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(174)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [174] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.SLICE_OF_COEURL_MEAT) then\n                        return quest:progressEvent(171)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(175),\n            },\n\n            onEventFinish =\n            {\n                [171] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n        {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_MY_SISTER) then\n                        return quest:event(122):replaceDefault()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/DNC_AF1_The_Unfinished_Waltz.lua"]={["Path"]="scripts/quests/jeuno/DNC_AF1_The_Unfinished_Waltz.lua",["SHA256"]="98f1f568d03939a2d39d52691f146930939d45dbe8ed1190a076f298c4a93ada",["Text"]="-----------------------------------\n-- The Unfinished Waltz\n-----------------------------------\n-- !addquest 3 96\n-- Laila : !pos -54.045 -1 100.996 244\n-- qm1   : !pos -157.16 -8 596.9 89\n-----------------------------------\nlocal graubergID = zones[xi.zone.GRAUBERG_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_UNFINISHED_WALTZ)\n\nquest.reward =\n{\n    item  = xi.item.WAR_HOOP,\n    title = xi.title.PROMISING_DANCER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.DNC and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] = quest:progressEvent(10129),\n\n            onEventFinish =\n            {\n                [10129] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:seenKeyItem(xi.keyItem.THE_ESSENCE_OF_DANCE) then\n                        return quest:progressEvent(10133)\n                    else\n                        return quest:progressEvent(10130)\n                    end\n                end,\n            },\n\n            ['Rhea_Myuliah'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(10131)\n                    else\n                        return quest:progressEvent(10132)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10131] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [10133] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        -- Set mustZone and Timer for \"The Road to Divadom\" Quest\n\n                        player:setCharVar('Quest[3][97]Timer', VanadielUniqueDay() + 1)\n                        player:setLocalVar('Quest[3][97]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.THE_ESSENCE_OF_DANCE) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        local hippoEvent = quest:getLocalVar(player, 'hippoEvent')\n\n                        if\n                            hippoEvent == 0 and\n                            player:getMainJob() == xi.job.DNC\n                        then\n                            return quest:progressEvent(12)\n                        elseif\n                            hippoEvent == 1 and\n                            not GetMobByID(graubergID.mob.MIGRATORY_HIPPOGRYPH):isSpawned()\n                        then\n                            SpawnMob(graubergID.mob.MIGRATORY_HIPPOGRYPH):updateEnmity(player)\n                            return quest:messageSpecial(graubergID.text.A_SHIVER_RUNS_DOWN)\n                        elseif hippoEvent == 2 then\n                            return quest:progressEvent(13)\n                        else\n                            return quest:messageSpecial(graubergID.text.ATTEND_TO_MORE_PRESSING)\n                        end\n                    end\n                end,\n            },\n\n            ['Migratory_Hippogryph'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        quest:getLocalVar(player, 'hippoEvent') == 1\n                    then\n                        quest:setLocalVar(player, 'hippoEvent', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'hippoEvent', 1)\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.THE_ESSENCE_OF_DANCE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_DIVADOM)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila']        = quest:event(10134):replaceDefault(),\n            ['Rhea_Myuliah'] = quest:event(10135):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/DNC_AF2_The_Road_to_Divadom.lua"]={["Path"]="scripts/quests/jeuno/DNC_AF2_The_Road_to_Divadom.lua",["SHA256"]="77b84176dbaed3a2c81d176bb1d4eef94299e46ba5ccd6d41ffae0d7834cda91",["Text"]="-----------------------------------\n-- The Road to Divadom\n-----------------------------------\n-- !addquest 3 97\n-- Laila           : !pos -54.045 -1 100.996 244\n-- Rhea Myuliah    : !pos -56.220 -1 101.805 244\n-- Glowing Pebbles : !pos 104.2 4.1 443.6 82\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_DIVADOM)\n\nquest.reward =\n{\n    title = xi.title.STARDUST_DANCER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_UNFINISHED_WALTZ) and\n                player:getMainJob() == xi.job.DNC and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL and\n                not quest:getMustZone(player) and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] = quest:progressEvent(10136),\n\n            onEventFinish =\n            {\n                [10136] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() == xi.job.DNC\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(10137)\n                    elseif questProgress == 3 then\n                        -- Note: Retail handles this as a progression of onZoneIn events.\n                        -- Instead, we queue these here.\n\n                        player:startEvent(10139)\n                        player:startEvent(10214)\n                        player:startEvent(10215)\n                        return quest:progressEvent(10170)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(10170)\n                    end\n                end,\n            },\n\n            ['Rhea_Myuliah'] = quest:event(10138),\n\n            onEventFinish =\n            {\n                [10170] = function(player, csid, option, npc)\n                    local tightsItemID = xi.item.DANCERS_TIGHTS_F - player:getGender()\n\n                    if npcUtil.giveItem(player, tightsItemID) then\n                        quest:complete(player)\n\n                        player:setCharVar('Quest[3][98]Timer', VanadielUniqueDay() + 1)\n                        player:setLocalVar('Quest[3][98]mustZone', 1)\n                        player:setCharVar('HQuest[DncArtifact]Prog', 1)\n                    else\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['Glowing_Pebbles'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, xi.item.BLOCK_OF_YAGUDO_GLUE)\n                    then\n                        return quest:progressEvent(107)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(106)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 0 then\n                    return 105\n                end\n            end,\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [106] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [107] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.COMEBACK_QUEEN)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila']        = quest:event(10140):replaceDefault(),\n            ['Rhea_Myuliah'] = quest:event(10141):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/DNC_AF3_Comeback_Queen.lua"]={["Path"]="scripts/quests/jeuno/DNC_AF3_Comeback_Queen.lua",["SHA256"]="3593e91ed13f550404f1fe1e5d662c0b00da85fb36b4fe32e8b362e41dc487db",["Text"]="-----------------------------------\n-- Comeback Queen\n-----------------------------------\n-- !addquest 3 98\n-- Laila        : !pos -54.045 -1 100.996 244\n-- Rhea Myuliah : !pos -56.220 -1 101.805 244\n-- Harmodios    : !pos -79.928 -4.824 -135.114 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.COMEBACK_QUEEN)\n\nquest.reward =\n{\n    title = xi.title.ELEGANT_DANCER,\n}\n\n-- The final series of events for this quest involve several onZoneIn cutscenes back to back; however,\n-- the player doesn't move.  Increment quest var with this function, and force a zone in their current\n-- position.  This also ensures that things will resume where left off if the player disconnects.\nlocal function progressZone(player)\n    local currentPos = player:getPos()\n\n    quest:incrementVar(player, 'Prog', 1)\n    player:setPos(currentPos['x'], currentPos['y'], currentPos['z'], currentPos['rot'], xi.zone.UPPER_JEUNO)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.DNC and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_DIVADOM) and\n                not quest:getMustZone(player) and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] = quest:progressEvent(10143),\n\n            onEventFinish =\n            {\n                [10143] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WYATTS_PROPOSAL)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(10144)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(10147)\n                    elseif questProgress <= 3 then\n                        local progressOffset = questProgress - 2\n\n                        if VanadielUniqueDay() < quest:getVar(player, 'Timer') then\n                            -- Timer active - First time: 10148, Repeat: 10152\n                            return quest:progressEvent(10148 + (4 * progressOffset))\n                        else\n                            return quest:progressEvent(10151, progressOffset)\n                        end\n                    elseif questProgress == 8 then\n                        return quest:progressEvent(10154)\n                    end\n                end,\n            },\n\n            ['Olgald'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        -- Blocking event after the Dancer Tailor series (10167 and 10168), for those quests\n                        -- 10167 is a progressEvent, 10168 is oncePerZone()\n\n                        return quest:event(10146):setPriority(995)\n                    elseif questProgress <= 2 then\n                        return quest:event(10150):setPriority(995)\n                    elseif questProgress == 3 then\n                        return quest:event(10153):setPriority(995)\n                    end\n                end,\n            },\n\n            ['Rhea_Myuliah'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 1 then\n                        return quest:progressEvent(10145)\n                    elseif questProgress <= 3 then\n                        return quest:progressEvent(10149)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                local questProgress = quest:getVar(player, 'Prog')\n\n                if questProgress == 4 then\n                    return 10208\n                elseif questProgress == 5 then\n                    return 10209\n                elseif questProgress == 6 then\n                    return 10210\n                elseif questProgress == 7 then\n                    return 10211\n                end\n            end,\n\n            onEventFinish =\n            {\n                [10147] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [10151] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Prog', 3)\n                    else\n                        progressZone(player)\n                    end\n                end,\n\n                [10154] = function(player, csid, option, npc)\n                    local dancersCasaque = xi.item.DANCERS_CASAQUE_F - player:getGender()\n\n                    if npcUtil.giveItem(player, dancersCasaque) then\n                        quest:complete(player)\n\n                        player:setCharVar('Quest[3][99]Timer', VanadielUniqueDay() + 1)\n                        player:setLocalVar('Quest[3][99]mustZone', 1)\n                    end\n                end,\n\n                [10208] = function(player, csid, option, npc)\n                    progressZone(player)\n                end,\n\n                [10209] = function(player, csid, option, npc)\n                    progressZone(player)\n                end,\n\n                [10210] = function(player, csid, option, npc)\n                    progressZone(player)\n                end,\n\n                [10211] = function(player, csid, option, npc)\n                    local dancersCasaque = xi.item.DANCERS_CASAQUE_F - player:getGender()\n\n                    if npcUtil.giveItem(player, dancersCasaque) then\n                        quest:complete(player)\n\n                        player:setCharVar('Quest[3][99]Timer', VanadielUniqueDay() + 1)\n                        player:setLocalVar('Quest[3][99]mustZone', 1)\n                    else\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Harmodios'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(490)\n                    else\n                        return quest:event(491):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [490] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.WYATTS_PROPOSAL)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            -- TODO: This condition may change with the implementation of\n            -- Dancer Limit Break\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Alfrieda']     = quest:event(10157):replaceDefault(),\n            ['Finnela']      = quest:event(10159):replaceDefault(),\n            ['Laila']        = quest:event(10154):replaceDefault(),\n            ['Olgald']       = quest:event(10156):replaceDefault(),\n            ['Rhea_Myuliah'] = quest:event(10155):replaceDefault(),\n            ['Turlough']     = quest:event(10158):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Deal_with_Tenshodo.lua"]={["Path"]="scripts/quests/jeuno/Deal_with_Tenshodo.lua",["SHA256"]="96d9a4c4d223088d3e52692f259893c33d13ee8bd6c45b9487ba97b6b7da319c",["Text"]="-----------------------------------\n-- Deal with Tenshodo\n-----------------------------------\n-- Log ID: 3, Quest ID: 26\n-- Garnev : !pos 30 4 -36 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.DEAL_WITH_TENSHODO)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.NORG,\n    keyItem  = xi.keyItem.CLOCK_TOWER_OIL,\n    title    = xi.title.TRADER_OF_RENOWN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CLOCK_MOST_DELICATE) == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Garnev'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getFameLevel(xi.fameArea.NORG) >= 2 then\n                        return quest:progressEvent(167)\n                    else\n                        return quest:event(168)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [167] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Garnev'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.GOLD_ORCMASK) then\n                        return quest:progressEvent(166)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [166] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    }\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Ducal_Hospitality.lua"]={["Path"]="scripts/quests/jeuno/Ducal_Hospitality.lua",["SHA256"]="4c5ad41c1efee61d66ece3e4749c783b45d5ed008a73bf112a663933d96e9566",["Text"]="-----------------------------------\n-- Ducal Hospitality\n-- Taillegeas - !gotoid 17772720\n-- Log ID [3] - Quest ID [68]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.DUCAL_HOSPITALITY)\n\nlocal questItemSets =\n{\n    [1] =\n    {\n        items =\n        {\n            xi.item.HANDFUL_OF_COUNTERFEIT_GIL,\n            xi.item.LOAF_OF_GOBLIN_BREAD,\n            xi.item.GOBLIN_DOLL,\n            xi.item.GOBLIN_MUSHPOT,\n            xi.item.GOBLIN_PIE,\n        },\n        textOption = 0,\n    },\n\n    [2] =\n    {\n        items =\n        {\n            xi.item.PILE_OF_CHOCOBO_BEDDING,\n            xi.item.SET_OF_KAISERIN_COSMETICS,\n            xi.item.MY_FIRST_MAGIC_KIT,\n        },\n        textOption = 1,\n    },\n\n    [3] =\n    {\n        items =\n        {\n            xi.item.PIECE_OF_EASTERN_PAPER,\n            xi.item.SHURIKEN,\n            xi.item.SILVER_OBI,\n            xi.item.TONOSAMA_RICE_BALL,\n        },\n        textOption = 4,\n    },\n\n    [4] =\n    {\n        items =\n        {\n            xi.item.DART,\n            xi.item.KONGOU_INAHO,\n            xi.item.NYUMOMO_DOLL,\n            xi.item.CONE_OF_SNOLL_GELATO,\n        },\n        textOption = 4,\n    },\n\n    [5] =\n    {\n        items =\n        {\n            xi.item.COPY_OF_FERNANS_DIARIES,\n            xi.item.NAPHILLE_POCHETTE,\n            xi.item.SPHENE_EARRING,\n            xi.item.TURQUOISE_RING,\n        },\n        textOption = 4,\n    }\n}\n\nquest.reward =\n{\n    gil = 4000,\n    title = xi.title.DUCAL_DUPE,\n}\n\nquest.sections =\n{\n    -- Quest: AVAILABLE\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.A_VESSEL_WITHOUT_A_CAPTAIN) and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 4\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Taillegeas'] =\n            {\n                onTrigger = function(player, npc)\n                    local warriorsPathComplete = player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) and 1 or 0\n                    local questItemSet = math.randomInt(1, #questItemSets)\n                    quest:setVar(player, 'ItemSet', questItemSet)\n                    return quest:progressEvent(10057, {\n                        [0] = warriorsPathComplete,\n                        [1] = questItemSets[questItemSet].items[1],\n                        [2] = questItemSets[questItemSet].items[2],\n                        [3] = questItemSets[questItemSet].items[3],\n                        [4] = questItemSets[questItemSet].items[4] or 0,\n                        [5] = questItemSets[questItemSet].items[5] or 0,\n                        [6] = questItemSets[questItemSet].textOption,\n                    })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10057] = function(player, csid, option, npc)\n                    if option == 10 then\n                        return\n                    else\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Quest: ACCEPTED\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Taillegeas'] =\n            {\n                onTrigger = function(player, npc)\n                    local warriorsPathComplete = player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) and 1 or 0\n                    local questItemSet = quest:getVar(player, 'ItemSet')\n                    return quest:progressEvent(10059, {\n                        [0] = warriorsPathComplete,\n                        [1] = questItemSets[questItemSet].items[1],\n                        [2] = questItemSets[questItemSet].items[2],\n                        [3] = questItemSets[questItemSet].items[3],\n                        [4] = questItemSets[questItemSet].items[4] or 0,\n                        [5] = questItemSets[questItemSet].items[5] or 0,\n                        [6] = questItemSets[questItemSet].textOption,\n                    })\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local warriorsPathComplete = player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) and 1 or 0\n                    local questItemSet = quest:getVar(player, 'ItemSet')\n                    if\n                        questItemSet > 0 and\n                        npcUtil.tradeHasExactly(trade, questItemSets[questItemSet].items)\n                    then\n                        return quest:progressEvent(10058, {\n                            [0] = warriorsPathComplete,\n                            [6] = questItemSet - 1,\n                        })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10058] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                        player:addFame(xi.fameArea.WINDURST, 5)\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n    },\n\n    -- Quest: COMPLETED\n    -- Allows for repeats of the quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Taillegeas'] =\n            {\n                onTrigger = function(player, npc)\n                    local warriorsPathComplete = player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) and 1 or 0\n                    local questItemSet = quest:getVar(player, 'ItemSet')\n                    if questItemSet > 0 then\n                        -- Quest has been re-started and an item-set was assigned to the player\n                        return quest:progressEvent(10059, {\n                            [0] = warriorsPathComplete,\n                            [1] = questItemSets[questItemSet].items[1],\n                            [2] = questItemSets[questItemSet].items[2],\n                            [3] = questItemSets[questItemSet].items[3],\n                            [4] = questItemSets[questItemSet].items[4] or 0,\n                            [5] = questItemSets[questItemSet].items[5] or 0,\n                            [6] = questItemSets[questItemSet].textOption,\n                        })\n                    elseif quest:getMustZone(player) then\n                        -- Player just completed the quest, needs to zone before re-starting\n                        return quest:progressEvent(10060, { [0] = warriorsPathComplete })\n                    else\n                        -- Player has the quest active and needs the item list again\n                        questItemSet = math.randomInt(1, #questItemSets)\n                        quest:setVar(player, 'ItemSet', questItemSet)\n                        return quest:progressEvent(10057, {\n                            [0] = warriorsPathComplete,\n                            [1] = questItemSets[questItemSet].items[1],\n                            [2] = questItemSets[questItemSet].items[2],\n                            [3] = questItemSets[questItemSet].items[3],\n                            [4] = questItemSets[questItemSet].items[4] or 0,\n                            [5] = questItemSets[questItemSet].items[5] or 0,\n                            [6] = questItemSets[questItemSet].textOption,\n                        })\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local warriorsPathComplete = player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_WARRIORS_PATH) and 1 or 0\n                    local questItemSet = quest:getVar(player, 'ItemSet')\n                    if\n                        questItemSet > 0 and\n                        npcUtil.tradeHasExactly(trade, questItemSets[questItemSet].items)\n                    then\n                        return quest:progressEvent(10058, {\n                            [0] = warriorsPathComplete,\n                            [6] = questItemSet - 1,\n                        })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10057] = function(player, csid, option, npc)\n                    if option == 10 then\n                        quest:setVar(player, 'ItemSet', 0)\n                    end\n                end,\n\n                [10058] = function(player, csid, option, npc)\n                    if not quest:getMustZone(player) then -- if we don't check this we get double reward immediately after first completion\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'ItemSet', 0)\n                        npcUtil.giveCurrency(player, 'gil', 4000)\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                        player:addFame(xi.fameArea.WINDURST, 5)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Empty_Memories.lua"]={["Path"]="scripts/quests/jeuno/Empty_Memories.lua",["SHA256"]="ce6129a58accfa957f02e9e87dd8de7895f9a6e5efe220a01071c9cce9fefde2",["Text"]="-----------------------------------\n-- Empty Memories\n-----------------------------------\n-- !addquest 3 70\n-- Harith : !pos -4.349 1 134.014 243\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.EMPTY_MEMORIES)\n\nquest.reward = {}\n\nlocal rewardItems =\n{\n--  Awarded Item id                       Required Items for Trade\n    [xi.item.BOTTLE_OF_HYSTEROANIMA] = { tradeItem = xi.item.RECOLLECTION_OF_PAIN,      gil = 2000 },\n    [xi.item.BOTTLE_OF_PSYCHOANIMA ] = { tradeItem = xi.item.RECOLLECTION_OF_FEAR,      gil = 2000 },\n    [xi.item.BOTTLE_OF_TERROANIMA  ] = { tradeItem = xi.item.RECOLLECTION_OF_GUILT,     gil = 2000 },\n    [xi.item.HAMAYUMI              ] = { tradeItem = xi.item.RECOLLECTION_OF_SUFFERING, gil =  nil },\n    [xi.item.STONE_GORGET          ] = { tradeItem = xi.item.RECOLLECTION_OF_ANXIETY,   gil =  nil },\n    [xi.item.DIA_WAND              ] = { tradeItem = xi.item.RECOLLECTION_OF_ANIMOSITY, gil =  nil },\n}\n\nlocal memoriesOnEventFinish = function(player, csid, option, npc)\n    local rewardItem = quest:getLocalVar(player, 'rewardItem')\n\n    if npcUtil.giveItem(player, rewardItem) then\n        player:confirmTrade()\n\n        if rewardItems[rewardItem].gil then\n            player:delGil(rewardItems[rewardItem].gil)\n        end\n\n        if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_ACCEPTED then\n            player:addFame(xi.fameArea.SANDORIA, 5)\n            player:addFame(xi.fameArea.BASTOK, 5)\n            player:addFame(xi.fameArea.WINDURST, 5)\n        end\n\n        quest:complete(player)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            (player:getCurrentMission(xi.mission.log_id.COP) >= xi.mission.id.cop.THE_MOTHERCRYSTALS or\n            xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.BELOW_THE_ARKS, 'Option') > 0)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Harith'] = quest:progressEvent(113),\n\n            onEventFinish =\n            {\n                [113] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Harith'] =\n            {\n                onTrade = function(player, npc, trade)\n                    for rewardItemId, requiredItems in pairs(rewardItems) do\n                        if trade:hasItemQty(requiredItems.tradeItem, 1) then\n                            if requiredItems.gil and trade:getGil() ~= requiredItems.gil then\n                                return quest:event(108, requiredItems.gil)\n                            end\n\n                            local eventId = requiredItems.gil and 109 or 110\n\n                            trade:confirmItem(requiredItems.tradeItem, 1)\n                            quest:setLocalVar(player, 'rewardItem', rewardItemId)\n\n                            return quest:progressEvent(eventId)\n                        end\n                    end\n                end,\n\n                onTrigger = quest:event(114),\n            },\n\n            onEventFinish =\n            {\n                [109] = memoriesOnEventFinish,\n                [110] = memoriesOnEventFinish,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
